import Vue from 'vue'
import Router from 'vue-router'
import HomePage from '@/views/HomePage'
// Remove or fix the imports that are causing errors

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'HomePage',
      component: HomePage
    },
    {
      path: '/school-overview',
      name: 'SchoolOverview',
      component: () => import('../views/SchoolOverview.vue')
    },
    {
      path: '/about',
      name: 'AboutPage',
      // Use dynamic import instead of static import for components that might not exist
      component: () => import('../views/AboutPage.vue')
    },
    // Use the same pattern for other routes
  ]
})
